+                await run_sync_io(os.remove, path)
+                logger.info("Deleted orphan session file: %s", path)
+                return True
+            except FileNotFoundError:
+                return False
+            except OSError as exc:
+                logger.warning(
+                    "Failed to delete orphan session file %s: %s",
+                    path,
+                    exc,
+                )
+                return False
